'use strict';
const $=id=>document.getElementById(id);
const keys=['x','y','heading','bx','by','speed','wheelbase','wifi_ref','exponent','ble_radius','stop_at'];
const presets={straight:{x:0,y:0,heading:0,bx:1,by:0},diagonal:{x:0,y:0,heading:0,bx:1,by:1},far:{x:-2,y:-1,heading:0,bx:1,by:1},behind:{x:0,y:0,heading:0,bx:-1,by:0},close:{x:0,y:0,heading:0,bx:.15,by:0}};
let run=null,playing=false,playTime=0,frame=null,busy=false,chartMode='wifi',logMode='decisions',lastLogCount=-1;
let view={x:.5,y:0,span:5},drag=null,history=[],config=null;
const fmt=(v,n=2)=>Number(v).toFixed(n);
const norm=a=>((a%360)+360)%360;
const clock=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}.${Math.floor((t%1)*10)}`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function scenario(){const s={horizon:1000,corrupt_reply:0};for(const k of keys)s[k]=Number($(k).value);return s;}
function showError(message){$('error').hidden=!message;$('error').textContent=message||'';}
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Simulator':'1'},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||`Request failed (${r.status})`);return d;}
function populateRefs(refs){const old=$('branch').value;$('branch').replaceChildren();for(const r of refs){const o=document.createElement('option');o.value=r.name;o.textContent=`${r.name} ${r.supported?'':'· needs adapter'}`;o.disabled=!r.supported;$('branch').append(o);}const o=document.createElement('option');o.value='working-tree';o.textContent='Current working tree · saved edits';$('branch').append(o);if(old&&[...$('branch').options].some(o=>o.value===old))$('branch').value=old;else $('branch').value='origin/main';branchNote();}
function branchNote(){const custom=$('customRef').value.trim(),current=config?.refs.find(r=>r.name===$('branch').value);$('branchNote').textContent=custom?`Next run: ${custom} · both car and AP1` : current?`${current.commit} · both car and AP1 from this branch`:'Snapshots saved car and AP1 source files.';const details=$('sourceDetails');details.replaceChildren();if(!custom&&current?.supported){const car=document.createElement('div'),beacon=document.createElement('div');car.textContent='Car: '+current.car_source;beacon.textContent='AP1: '+current.beacon_source;details.append(car,beacon);}else details.textContent='Source paths are resolved and recorded when you build.';}

function previewFrame(){const s=scenario(),distance=Math.hypot(s.x-s.bx,s.y-s.by);return {t:0,x:s.x,y:s.y,heading:s.heading,gyro_heading:0,distance,closest:distance,path:0,wifi:Math.max(-126,Math.min(-1,s.wifi_ref-10*s.exponent*Math.log10(Math.max(.01,distance)))),ble:Math.max(-126,Math.min(-1,-50-10*s.exponent*Math.log10(Math.max(.01,distance)/s.ble_radius))),left:0,right:0,left_pwm:0,right_pwm:0,wifi_observed:-127,ble_observed:-127,wifi_scans:0,ble_reports:0,ble_attempts:0,faults:0,ble_state:'Idle',peer_state:'Advertising',ble_samples:0,ble_close_count:0,ble_filtered:-127,ble_threshold:-50,rx_bytes:0,tx_bytes:0};}
function resetPreview(fit=false){playing=false;run=null;playTime=0;frame=previewFrame();lastLogCount=-1;for(const id of ['playBtn','stepBtn','endBtn','timeline','csvBtn','jsonBtn'])$(id).disabled=true;$('editStartBtn').hidden=true;$('timeline').value=0;$('timeline').max=1;$('duration').textContent='0:00';$('outcome').hidden=true;$('events').innerHTML='<div class="empty">Run an experiment to inspect the firmware’s decisions and sensor readings.</div>';$('arenaState').textContent='READY TO RUN';$('mapHint').textContent='Drag car to move · drag circle to rotate · scroll to zoom';$('playBtn').textContent='▶';$('provenance').textContent='Native C execution · deterministic hardware model · local only';if(fit)fitView();render();}
function applyScenario(s){for(const k of keys)if(k in s)$(k).value=fmt(s[k]);resetPreview(true);}
function fitView(){const s=run?.scenario||scenario();const pts=run?run.frames:[{x:s.x,y:s.y}];let minx=s.bx,maxx=s.bx,miny=s.by,maxy=s.by;for(const p of pts){minx=Math.min(minx,p.x);maxx=Math.max(maxx,p.x);miny=Math.min(miny,p.y);maxy=Math.max(maxy,p.y);}const ratio=$('arena').clientWidth/Math.max(1,$('arena').clientHeight);view={x:(minx+maxx)/2,y:(miny+maxy)/2,span:Math.max(3,maxy-miny+1.5,(maxx-minx+1.5)/ratio)};}
function canvasContext(id){const c=$(id),rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;if(c.width!==Math.round(rect.width*dpr)||c.height!==Math.round(rect.height*dpr)){c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr);}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{ctx,w:rect.width,h:rect.height};}
function worldToScreen(x,y,w,h){const scale=h/view.span;return{x:w/2+(x-view.x)*scale,y:h/2-(y-view.y)*scale};}
function screenToWorld(x,y,w,h){const scale=h/view.span;return{x:view.x+(x-w/2)/scale,y:view.y-(y-h/2)/scale};}
function headingHandle(f,w,h){const p=worldToScreen(f.x,f.y,w,h),angle=(f.heading+90)*Math.PI/180;return{x:p.x+50*Math.cos(angle),y:p.y-50*Math.sin(angle)};}
function drawHeadingHandle(c,f,w,h){
  const p=worldToScreen(f.x,f.y,w,h),handle=headingHandle(f,w,h),active=drag?.kind==='heading';
  c.save();c.strokeStyle=active?'#6ee7bb90':'#6ee7bb35';c.lineWidth=1;c.setLineDash([3,5]);c.beginPath();c.arc(p.x,p.y,50,0,Math.PI*2);c.stroke();c.setLineDash([]);
  c.strokeStyle='#6ee7bb80';c.beginPath();c.moveTo(p.x+(handle.x-p.x)*.55,p.y+(handle.y-p.y)*.55);c.lineTo(handle.x,handle.y);c.stroke();
  c.fillStyle=active?'#6ee7bb':'#163a30';c.strokeStyle='#6ee7bb';c.lineWidth=2;c.beginPath();c.arc(handle.x,handle.y,9,0,Math.PI*2);c.fill();c.stroke();
  c.fillStyle=active?'#163a30':'#a6f4d5';c.beginPath();c.arc(handle.x,handle.y,2.5,0,Math.PI*2);c.fill();
  const label=`Rotate · ${fmt(norm(f.heading),1)}°`;c.font='10px ui-monospace,monospace';const width=c.measureText(label).width;
  const lx=Math.max(8,Math.min(w-width-8,handle.x-width/2)),ly=handle.y<30?handle.y+26:handle.y-18;
  c.fillStyle='#10171fee';c.fillRect(lx-4,ly-11,width+8,16);c.fillStyle='#a6d9c3';c.fillText(label,lx,ly);c.restore();
}
function drawArena(){const {ctx:c,w,h}=canvasContext('arena');if(!w||!h)return;c.clearRect(0,0,w,h);const s=run?.scenario||scenario(),f=frame||previewFrame(),scale=h/view.span;
  const lo=screenToWorld(0,h,w,h),hi=screenToWorld(w,0,w,h);const grid=view.span>20?5:1;
  c.lineWidth=1;for(let x=Math.ceil(lo.x/grid)*grid;x<=hi.x;x+=grid){const p=worldToScreen(x,0,w,h);c.strokeStyle=x===0?'#2a3b47':'#1b2934';c.beginPath();c.moveTo(p.x,0);c.lineTo(p.x,h);c.stroke();}for(let y=Math.ceil(lo.y/grid)*grid;y<=hi.y;y+=grid){const p=worldToScreen(0,y,w,h);c.strokeStyle=y===0?'#2a3b47':'#1b2934';c.beginPath();c.moveTo(0,p.y);c.lineTo(w,p.y);c.stroke();}
  const b=worldToScreen(s.bx,s.by,w,h),p=worldToScreen(f.x,f.y,w,h),start=worldToScreen(s.x,s.y,w,h);
  const grad=c.createRadialGradient(b.x,b.y,0,b.x,b.y,scale*2);grad.addColorStop(0,'#ffca7512');grad.addColorStop(1,'#ffca7500');c.fillStyle=grad;c.beginPath();c.arc(b.x,b.y,scale*2,0,Math.PI*2);c.fill();
  for(const radius of [.5,1,2,3]){c.strokeStyle='#ffca751b';c.setLineDash([3,6]);c.beginPath();c.arc(b.x,b.y,radius*scale,0,Math.PI*2);c.stroke();}c.setLineDash([]);
  c.fillStyle='#ffca7510';c.strokeStyle='#ffca7580';c.beginPath();c.arc(b.x,b.y,(s.ble_radius*Math.pow(10,(-50-(f.ble_threshold??-50))/(10*s.exponent)))*scale,0,Math.PI*2);c.fill();c.stroke();
  if(run){c.strokeStyle='#6ee7bb90';c.lineWidth=2;c.beginPath();let first=true;for(const pt of run.frames){if(pt.t>playTime)break;const q=worldToScreen(pt.x,pt.y,w,h);if(first){c.moveTo(q.x,q.y);first=false;}else c.lineTo(q.x,q.y);}c.stroke();c.strokeStyle='#638477';c.setLineDash([3,3]);c.beginPath();c.arc(start.x,start.y,9,0,Math.PI*2);c.stroke();c.setLineDash([]);c.fillStyle='#77978a';c.font='9px ui-monospace,monospace';c.fillText('START',start.x+13,start.y+4);}
  c.strokeStyle='#8ba2af65';c.lineWidth=1;c.setLineDash([4,5]);c.beginPath();c.moveTo(p.x,p.y);c.lineTo(b.x,b.y);c.stroke();c.setLineDash([]);
  const mx=(p.x+b.x)/2,my=(p.y+b.y)/2;c.font='10px ui-monospace,monospace';const text=fmt(f.distance)+' m',tw=c.measureText(text).width;c.fillStyle='#10171fee';c.fillRect(mx-tw/2-6,my-10,tw+12,19);c.fillStyle='#aabcc8';c.fillText(text,mx-tw/2,my+3);
  c.shadowColor='#ffca7560';c.shadowBlur=18;c.fillStyle='#ffca75';c.beginPath();c.arc(b.x,b.y,9,0,Math.PI*2);c.fill();c.shadowBlur=0;c.strokeStyle='#ffca7580';c.beginPath();c.arc(b.x,b.y,15,0,Math.PI*2);c.stroke();c.fillStyle='#192127';c.beginPath();c.arc(b.x,b.y,3,0,Math.PI*2);c.fill();c.fillStyle='#ffca75';c.font='bold 10px '+getComputedStyle(document.body).fontFamily;c.fillText('AP1',b.x+21,b.y-3);c.font='9px ui-monospace,monospace';c.fillStyle='#b0a18a';c.fillText('BEACON',b.x+21,b.y+11);
  c.save();c.translate(p.x,p.y);c.rotate(-f.heading*Math.PI/180);const size=Math.max(18,Math.min(30,.22*scale));c.fillStyle='#0c1116';c.strokeStyle='#7ca997';c.lineWidth=1;c.fillRect(-size*.6,-size*.58,size*.72,5);c.strokeRect(-size*.6,-size*.58,size*.72,5);c.fillRect(-size*.6,size*.58-5,size*.72,5);c.strokeRect(-size*.6,size*.58-5,size*.72,5);c.fillStyle='#193e32';c.strokeStyle='#6ee7bb';c.lineWidth=1.5;c.beginPath();c.roundRect(-size*.7,-size*.43,size*1.4,size*.86,5);c.fill();c.stroke();c.fillStyle='#6ee7bb';c.beginPath();c.moveTo(size*.85,0);c.lineTo(size*.3,-size*.21);c.lineTo(size*.3,size*.21);c.closePath();c.fill();c.fillStyle='#578e79';c.fillRect(-size*.3,-size*.2,size*.3,size*.4);c.restore();
  c.fillStyle='#8fbcaa';c.font='9px ui-monospace,monospace';c.fillText('CAR',p.x-11,p.y+33);
  if(!run&&!busy)drawHeadingHandle(c,f,w,h);
  const bar=scale*grid;c.strokeStyle='#607786';c.beginPath();c.moveTo(19,h-39);c.lineTo(19+bar,h-39);c.stroke();c.fillStyle='#718797';c.font='9px ui-monospace,monospace';c.fillText(`${grid} m`,20,h-44);
}
function drawChart(){const {ctx:c,w,h}=canvasContext('chart');c.clearRect(0,0,w,h);const pad={l:43,r:17,t:8,b:21},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b;const frames=run?.frames||[frame||previewFrame()];const vals=frames.map(f=>f[chartMode]);let min=Math.min(...vals),max=Math.max(...vals);if(chartMode==='distance'){min=0;max=Math.max(1,max*1.1);}else{min=Math.floor((min-3)/5)*5;max=Math.ceil((Math.max(max,chartMode==='ble'?-50:-Infinity)+3)/5)*5;}const duration=run?.result.t||10;const px=t=>pad.l+t/duration*cw,py=v=>pad.t+(max-v)/(max-min||1)*ch;
  c.font='8px ui-monospace,monospace';for(let i=0;i<=3;i++){const val=min+(max-min)*i/3,y=py(val);c.strokeStyle='#25323d';c.lineWidth=1;c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();c.fillStyle='#7f95a7';c.fillText(fmt(val,chartMode==='distance'?1:0),8,y+3);}for(let i=0;i<=4;i++){const t=duration*i/4;c.fillStyle='#7f95a7';c.fillText(`${Math.round(t)}s`,px(t)-7,h-4);}
  if(chartMode==='ble'){const y=py(frames[0].ble_threshold??-50);c.strokeStyle='#ffca7580';c.setLineDash([4,4]);c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();c.setLineDash([]);c.fillStyle='#ffca75';c.fillText('firmware threshold',w-127,y-4);}
  c.lineWidth=1.7;c.strokeStyle=chartMode==='ble'?'#ffca75':'#6ee7bb';c.beginPath();let first=true;for(const f of frames){if(f.t>playTime)break;if(first){c.moveTo(px(f.t),py(f[chartMode]));first=false;}else c.lineTo(px(f.t),py(f[chartMode]));}c.stroke();
  if(chartMode!=='distance'&&run){let prev=-1;c.fillStyle='#8ab5ff';for(const f of frames){if(f.t>playTime)break;const count=chartMode==='wifi'?(f.wifi_reports??f.wifi_scans):f.ble_reports,obs=f[chartMode+'_observed'];if(count!==prev&&obs!==-127){c.beginPath();c.arc(px(f.t),py(obs),1.8,0,Math.PI*2);c.fill();prev=count;}}}
  if(run){c.strokeStyle='#d4e6ef60';c.beginPath();c.moveTo(px(playTime),pad.t);c.lineTo(px(playTime),h-pad.b);c.stroke();}else{c.fillStyle='#8d9ca9';c.font='10px sans-serif';c.fillText('Run an experiment to see the signal over time',pad.l+10,pad.t+ch/2);}
}
function setText(id,text){$(id).textContent=text;}
function renderStats(){const f=frame||previewFrame(),s=run?.scenario||scenario();$('distance').innerHTML=`${fmt(f.distance)} <small>m</small>`;$('path').innerHTML=`${fmt(f.path)} <small>m</small>`;$('closest').innerHTML=`${fmt(f.closest)} <small>m</small>`;$('elapsed').innerHTML=`${fmt(playTime,1)} <small>s</small>`;setText('clock',clock(playTime));$('timeline').value=playTime;
  $('carPosition').innerHTML=`${fmt(f.x)}, ${fmt(f.y)} <small>m</small>`;$('beaconPosition').innerHTML=`${fmt(s.bx)}, ${fmt(s.by)} <small>m</small>`;
  setText('worldHeading',`${fmt(norm(f.heading),1)}°`);setText('gyroHeading',`${fmt(f.gyro_heading,1)}°`);setText('wheelSpeeds',`${fmt(f.left)} / ${fmt(f.right)} m/s`);setText('wheelDuty',`${fmt(f.left_pwm,0)} / ${fmt(f.right_pwm,0)} %`);
  setText('wifiRead',f.wifi_observed===-127?'Not sampled':`${f.wifi_observed} dBm`);setText('wifiScans',f.wifi_scans);setText('bleState',f.ble_state);setText('buzzer',f.buzzer?'On · 2 kHz':'Off');setText('faults','0x'+f.faults.toString(16).padStart(4,'0'));$('faults').className=f.faults?'bad':'good';
  setText('motionBadge',Math.abs(f.left)+Math.abs(f.right)<.001?'Stationary':f.left*f.right<0?'Turning':f.left+f.right<0?'Reversing':'Forward');setText('peerState',f.peer_state);setText('wifiModel',`${fmt(f.wifi)} dBm`);setText('bleModel',`${fmt(f.ble)} dBm`);setText('bleRead',f.ble_observed===-127?'Not sampled':`${f.ble_observed} dBm`);setText('bleAverage',f.ble_filtered===-127?`${f.ble_samples} / 12 samples`:`${f.ble_filtered} dBm`);setText('closeCount',`${f.ble_close_count} / 3`);setText('bleCounts',`${f.ble_reports} / ${f.ble_attempts}`);setText('bytes',`${f.rx_bytes} / ${f.tx_bytes} bytes`);setText('peerCRC',f.peer_verified?'Verified':'Pending');setText('robotCRC',f.payload_verified?'Verified + final ACK':'Pending');$('peerCRC').className=f.peer_verified?'good':'';$('robotCRC').className=f.payload_verified?'good':'';
  if(run){const atEnd=playTime>=run.result.t-.001;$('arenaState').textContent=atEnd?(run.result.success?'PAYLOAD CONFIRMED':'FIRMWARE STOPPED'):playing?'PLAYING RECORDED EXECUTION':'PAUSED · INSPECT EXECUTION';$('outcome').hidden=!atEnd;}
}
function filteredLogs(){if(!run)return[];return run.logs.filter(l=>l.t<=playTime+.00001).filter(l=>logMode==='all'||(logMode==='faults'?/FAIL|FAULT:|ERROR|STOP LATCH/i.test(l.message):logMode==='ble'?l.source==='beacon'||/BLE|payload|Bluetooth|CRC|HANDSHAKE/i.test(l.message):/FOLLOW:|FOLLOW_POINT|DIRECTION|RETURN:|SIDE |APPROACH:|RESULT:|FAULT:|FAILED:|COMPLETION|PAYLOAD COMPLETE|START:|calibrat/i.test(l.message)));}
function renderLogs(){if(!run)return;const logs=filteredLogs();if(logs.length===lastLogCount)return;lastLogCount=logs.length;const el=$('events'),nearEnd=el.scrollTop+el.clientHeight>=el.scrollHeight-35;el.innerHTML=logs.slice(-250).map(l=>`<div class="log-row ${l.source==='beacon'?'beacon':''} ${/FAIL|FAULT:|ERROR/.test(l.message)?'fault':''}" data-time="${l.t}"><span class="time">${clock(l.t)}</span><span class="source">${escape(l.source)}</span><span class="message">${escape(l.message.trim())}</span></div>`).join('')||'<div class="empty">No matching events at this time. Play or scrub forward.</div>';if(nearEnd)el.scrollTop=el.scrollHeight;}
function render(){drawArena();drawChart();renderStats();renderLogs();}
function seek(t){if(!run)return;playTime=Math.min(run.result.t,Math.max(0,t));let lo=0,hi=run.frames.length-1;while(lo<hi){const m=Math.ceil((lo+hi)/2);if(run.frames[m].t<=playTime)lo=m;else hi=m-1;}frame=run.frames[lo];if(playTime>=run.result.t){playing=false;frame=run.frames.at(-1);$('playBtn').textContent='▶';}render();}
function loadRun(data,autoplay=false){run=data;playing=autoplay;playTime=0;frame=run.frames[0];lastLogCount=-1;for(const k of keys)if(k in run.scenario)$(k).value=fmt(run.scenario[k]);$('moving').checked=run.metadata.moving_samples;if([...$('branch').options].some(o=>o.value===run.metadata.ref)){$('branch').value=run.metadata.ref;$('customRef').value='';}else $('customRef').value=run.metadata.ref;branchNote();$('preset').value='custom';$('editStartBtn').hidden=false;$('mapHint').textContent='Edit start to arrange the next run · scroll to zoom';for(const id of ['playBtn','stepBtn','endBtn','timeline','csvBtn','jsonBtn'])$(id).disabled=false;$('timeline').max=run.result.t;$('duration').textContent=clock(run.result.t);$('playBtn').textContent=playing?'Ⅱ':'▶';$('outcome').classList.toggle('failed',!run.result.success);setText('outcomeIcon',run.result.success?'✓':'!');setText('outcomeTitle',run.result.success?'Payload confirmed by the firmware':'The firmware stopped without a confirmed payload');setText('outcomeDetail',run.result.success?`${fmt(run.result.t,1)} simulated seconds · ${fmt(run.result.path)} m travelled · both payload checks and final acknowledgement completed.`:run.result.failure_messages.join(' · ')||run.result.reason);setText('provenance',`${run.metadata.ref} · ${run.metadata.commit.slice(0,12)} · ${run.metadata.beacon_mode==='branch-firmware'?'car + AP1 branch firmware':'legacy run: car firmware + simulated peer'} · computed in ${run.result.wall_seconds}s`);setText('beaconSourceLabel',`${run.metadata.beacon_ssid||'I AM PICO W'} · ${run.metadata.beacon_mode==='branch-firmware'?'branch firmware':'legacy simulated peer'}`);fitView();seek(0);}
async function runExperiment(){if(busy)return;showError('');for(const k of keys){if(!$(k).reportValidity())return;}busy=true;playing=false;$('runBtn').disabled=true;$('runBtn').textContent='Compiling & simulating…';setText('connection','Native engine running…');try{const d=await api('/api/run',{ref:$('customRef').value.trim()||$('branch').value,scenario:scenario(),moving:$('moving').checked});loadRun(d,true);await loadHistory();setText('connection',`Native engine ready · ${d.metadata.commit.slice(0,7)}`);}catch(e){showError(e.message);setText('connection','Build / run failed · see setup panel');}finally{busy=false;$('runBtn').disabled=false;$('runBtn').innerHTML='<span>▶</span> Build & run experiment';}}
async function loadHistory(){history=await api('/api/runs');const cur=JSON.stringify(run?.scenario||scenario());$('history').innerHTML=history.length?`<table><thead><tr><th>BRANCH / COMMIT</th><th>OUTCOME</th><th>TIME</th><th>PATH</th><th>CLOSEST</th><th>SETUP</th><th></th></tr></thead><tbody>${history.map(r=>`<tr><td>${escape(r.metadata.ref)}<br><small>${escape(r.metadata.commit.slice(0,10))}</small></td><td class="${r.result.success?'pass':'fail'}">${r.result.success?'Confirmed':'Stopped'}</td><td>${fmt(r.result.t,1)} s</td><td>${fmt(r.result.path)} m</td><td>${fmt(r.result.closest)} m</td><td>${JSON.stringify(r.scenario)===cur&&r.metadata.moving_samples===!!$('moving').checked&&r.metadata.model_version===(run?.metadata.model_version||2)?'Same setup':'Different setup'}</td><td><button data-run="${escape(r.id)}">Inspect →</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Saved experiments will appear here.</div>';}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('runBtn').onclick=runExperiment;$('branch').onchange=()=>{$('customRef').value='';branchNote();};$('customRef').oninput=branchNote;$('fetchBtn').onclick=async()=>{try{$('fetchBtn').disabled=true;const d=await api('/api/fetch',{});config.refs=d.refs;populateRefs(d.refs);}catch(e){showError(e.message);}finally{$('fetchBtn').disabled=false;}};
$('preset').onchange=()=>{const s=presets[$('preset').value];if(s)applyScenario(s);};for(const k of keys)$(k).addEventListener('change',()=>{$('preset').value='custom';resetPreview();});$('moving').onchange=()=>resetPreview();
$('playBtn').onclick=()=>{if(!run)return;if(playTime>=run.result.t)seek(0);playing=!playing;$('playBtn').textContent=playing?'Ⅱ':'▶';renderStats();};$('stepBtn').onclick=()=>{playing=false;$('playBtn').textContent='▶';seek(playTime+.1);};$('endBtn').onclick=()=>seek(run.result.t);$('replayBtn').onclick=()=>{seek(0);playing=true;$('playBtn').textContent='Ⅱ';};$('timeline').oninput=()=>{playing=false;$('playBtn').textContent='▶';seek(Number($('timeline').value));};$('fitBtn').onclick=()=>{fitView();drawArena();};
$('chartTabs').onclick=e=>{const b=e.target.closest('[data-chart]');if(!b)return;chartMode=b.dataset.chart;for(const el of $('chartTabs').children)el.classList.toggle('active',el===b);setText('chartLegend',chartMode==='distance'?'Ground-truth distance':'Ideal signal');setText('chartOther',chartMode==='distance'?'Not available to the controller':'● Actual readings delivered to firmware');drawChart();};
$('evidenceTabs').onclick=e=>{const b=e.target.closest('[data-view]');if(!b)return;for(const el of $('evidenceTabs').children)el.classList.toggle('active',el===b);$('eventsView').hidden=b.dataset.view!=='events';$('historyView').hidden=b.dataset.view!=='history';$('logFilter').hidden=b.dataset.view!=='events';if(b.dataset.view==='history')loadHistory().catch(e=>showError(e.message));};$('logFilter').onchange=()=>{logMode=$('logFilter').value;lastLogCount=-1;renderLogs();};$('events').onclick=e=>{const row=e.target.closest('[data-time]');if(row){playing=false;$('playBtn').textContent='▶';seek(Number(row.dataset.time));}};$('history').onclick=async e=>{const b=e.target.closest('[data-run]');if(!b)return;try{loadRun(await api('/api/run/'+b.dataset.run));seek(run.result.t);}catch(e){showError(e.message);}};
$('jsonBtn').onclick=()=>run&&download(run.id+'.json',JSON.stringify(run,null,2));$('csvBtn').onclick=()=>{if(!run)return;const fields=Object.keys(run.frames[0]).filter(k=>k!=='type');const quote=v=>`"${String(v).replace(/"/g,'""')}"`;const text=[fields.map(quote).join(','),...run.frames.map(f=>fields.map(k=>quote(f[k])).join(','))].join('\n');download(run.id+'.csv',text,'text/csv');};$('saveScenario').onclick=()=>download('beacon-lab-scenario.json',JSON.stringify({scenario:scenario(),ref:$('customRef').value.trim()||$('branch').value,moving:$('moving').checked},null,2));$('importFile').onchange=async()=>{try{const f=$('importFile').files[0];if(!f)return;const data=JSON.parse(await f.text()),s=data.scenario||data;if(!s||typeof s!=='object')throw Error('Invalid scenario file');for(const k of keys)if(k in s&&!Number.isFinite(Number(s[k])))throw Error('Invalid value for '+k);applyScenario(s);if(data.ref)$('customRef').value=data.ref;branchNote();$('moving').checked=!!data.moving;$('preset').value='custom';showError('');}catch(e){showError(e.message);}finally{$('importFile').value='';}};
for(const id of ['aboutBtn','aboutFooter'])$(id).onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();$('about').onclick=e=>{if(e.target===$('about')){const r=$('about').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('about').close();}};
$('editStartBtn').onclick=()=>{if(!busy&&run){applyScenario(run.scenario);$('preset').value='custom';}};
const arena=$('arena');
function arenaTarget(x,y,r){
  const s=run?.scenario||scenario(),f=frame||previewFrame(),p=worldToScreen(f.x,f.y,r.width,r.height),b=worldToScreen(s.bx,s.by,r.width,r.height),handle=headingHandle(f,r.width,r.height);
  if(!run&&Math.hypot(x-handle.x,y-handle.y)<16)return 'heading';
  return Math.hypot(x-p.x,y-p.y)<28?'car':Math.hypot(x-b.x,y-b.y)<25?'beacon':'pan';
}
arena.onpointerdown=e=>{
  if(busy||e.button!==0||drag)return;
  const r=arena.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,f=frame||previewFrame(),p=worldToScreen(f.x,f.y,r.width,r.height),kind=arenaTarget(x,y,r);
  if(kind!=='pan'&&run)applyScenario({...run.scenario,x:f.x,y:f.y,heading:norm(f.heading)});
  $('preset').value='custom';drag={kind,pointerId:e.pointerId,x:e.clientX,y:e.clientY,vx:view.x,vy:view.y,headingOffset:f.heading-Math.atan2(p.y-y,x-p.x)*180/Math.PI};
  arena.style.cursor='grabbing';arena.setPointerCapture(e.pointerId);if(kind==='heading')drawArena();
};
arena.onpointermove=e=>{
  if(busy)return;
  const r=arena.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;
  if(!drag){arena.style.cursor=arenaTarget(x,y,r)==='pan'?'grab':'pointer';if(arenaTarget(x,y,r)==='heading')arena.style.cursor='grab';return;}
  if(e.pointerId!==drag.pointerId)return;
  if(drag.kind==='pan'){view.x=drag.vx-(e.clientX-drag.x)/(r.height/view.span);view.y=drag.vy+(e.clientY-drag.y)/(r.height/view.span);drawArena();return;}
  if(drag.kind==='heading'){
    const s=scenario(),center=worldToScreen(s.x,s.y,r.width,r.height),dx=x-center.x,dy=center.y-y;
    if(Math.hypot(dx,dy)<6)return;
    $('heading').value=fmt(norm(Number(fmt(Math.atan2(dy,dx)*180/Math.PI+drag.headingOffset))));resetPreview();return;
  }
  const p=screenToWorld(x,y,r.width,r.height),prefix=drag.kind==='beacon'?'b':'';$(prefix+'x').value=fmt(Math.max(-50,Math.min(50,p.x)));$(prefix+'y').value=fmt(Math.max(-50,Math.min(50,p.y)));resetPreview();
};
function endArenaDrag(e){if(drag&&e.pointerId===drag.pointerId){drag=null;arena.style.cursor='grab';drawArena();}}
arena.onpointerup=endArenaDrag;arena.onpointercancel=endArenaDrag;arena.onlostpointercapture=endArenaDrag;
arena.addEventListener('wheel',e=>{e.preventDefault();view.span=Math.max(1,Math.min(120,view.span*Math.exp(e.deltaY*.001)));drawArena();},{passive:false});
new ResizeObserver(()=>{drawArena();drawChart();}).observe($('arena').parentElement);new ResizeObserver(drawChart).observe($('chart'));
let last=performance.now(),lastPaint=0,accumulator=0;function loop(now){const dt=Math.min(.15,(now-last)/1000);last=now;if(playing&&run){accumulator+=dt;if(now-lastPaint>32){seek(playTime+accumulator*Number($('playSpeed').value));accumulator=0;lastPaint=now;}}else accumulator=0;requestAnimationFrame(loop);}requestAnimationFrame(loop);
async function init(){resetPreview(true);try{config=await api('/api/config');populateRefs(config.refs);setText('connection','Native engine ready · local only');await loadHistory();}catch(e){showError(e.message);setText('connection','Local engine unavailable');}}init();
